type RecordValue = Record<string, unknown>;
type DocumentRecord = RecordValue;
type SectionRecord = RecordValue;
type TopicRecord = RecordValue;
type VersionRecord = RecordValue;
type ImportRunRecord = RecordValue;
type SearchResultRecord = RecordValue;
type ProjectRecord = { id: number; name?: string };
type DiffRecord = RecordValue & { changes?: RecordValue[]; leftId?: string; rightId?: string };
type FilterKey = "product" | "sampleManagerVersion" | "solution" | "module" | "documentType" | "language" | "authority" | "status";
type DocumentFilters = Record<FilterKey, string>;
type ImportStage = "idle" | "uploading" | "queued" | "processing" | "succeeded" | "failed";

const emptyFilters: DocumentFilters = { product: "", sampleManagerVersion: "", solution: "", module: "", documentType: "", language: "", authority: "", status: "" };
const filterLabels: Array<[FilterKey, string]> = [["product", "Product"], ["sampleManagerVersion", "Version"], ["solution", "Solution"], ["module", "Module"], ["documentType", "Type"], ["language", "Language"], ["authority", "Authority"], ["status", "Status"]];

function text(value: unknown, fallback = "—"): string { return value === undefined || value === null || value === "" ? fallback : String(value); }
function record(value: unknown): RecordValue { return value && typeof value === "object" && !Array.isArray(value) ? value as RecordValue : {}; }
function records(value: unknown): RecordValue[] { return Array.isArray(value) ? value.filter((item): item is RecordValue => Boolean(item && typeof item === "object" && !Array.isArray(item))) : []; }
function numberValue(value: unknown, fallback = 0): number { const parsed = Number(value); return Number.isFinite(parsed) ? parsed : fallback; }
function formatDate(value: unknown): string { const date = new Date(text(value, "")); return Number.isNaN(date.getTime()) ? "—" : date.toLocaleString(); }
function jsonObject(value: unknown): RecordValue { if (value && typeof value === "object" && !Array.isArray(value)) return value as RecordValue; try { return record(JSON.parse(text(value, "{}"))); } catch { return {}; } }
function statusTone(value: unknown): "mint" | "sun" | "coral" | "neutral" { const state = text(value, "unknown"); if (/failed|error|deprecated|rejected/i.test(state)) return "coral"; if (/warning|partial|needs_review|stale|queued|running|pending/i.test(state)) return "sun"; if (/approved|succeeded|verified|ready|healthy|accepted|active/i.test(state)) return "mint"; return "neutral"; }
function statusLabel(value: unknown): string { return text(value, "Unknown").replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase()); }

function PageHeader({ title, description, actions }: { title: string; description: string; actions?: ReactNode }) {
  return <header className="ui-page-header"><div><h1>{title}</h1><p className="ui-page-header-description">{description}</p></div>{actions && <div className="ui-page-header-actions">{actions}</div>}</header>;
}
function PageTabs({ active, scope }: { active: string; scope: KnowledgeScope }) {
  const { user } = useAuth();
  const tabs: ReadonlyArray<readonly [string, string, string]> = user?.isAdmin
    ? [["docs", "Documents", "/knowledge/product-docs"], ["imports", "Imports", "/knowledge/product-docs/imports"], ["topics", "Topics", "/knowledge/product-docs/topics"], ["versions", "Versions and diffs", "/knowledge/product-docs/versions"], ["search", "Search", "/knowledge/product-docs/search"]]
    : [["docs", "Documents", "/knowledge/product-docs"], ["topics", "Topics", "/knowledge/product-docs/topics"], ["versions", "Versions and diffs", "/knowledge/product-docs/versions"], ["search", "Search", "/knowledge/product-docs/search"]];
  return <nav className="ui-page-tabs" aria-label="Product docs sections"><div className="flex flex-wrap gap-2">{tabs.map(([key, label, path]) => <Link key={key} to={withKnowledgeScope(path, scope)} className={`ui-button ui-button-ghost ui-button-sm ${active === key ? "ui-button-accent" : ""}`}>{label}</Link>)}</div></nav>;
}
function StatusPill({ value }: { value: unknown }) { const tone = statusTone(value); return <span className={`ui-status ui-status-${tone === "mint" ? "ok" : tone === "sun" ? "warn" : tone === "coral" ? "bad" : "neutral"}`}><span className="ui-status-dot" />{statusLabel(value)}</span>; }
function Badge({ children, tone = "neutral" }: { children: ReactNode; tone?: "mint" | "sun" | "coral" | "iris" | "neutral" }) { return <span className={`ui-badge ui-badge-${tone === "neutral" ? "" : tone}`}>{children}</span>; }
function EmptyState({ title, description, action }: { title: string; description: string; action?: ReactNode }) { return <section className="ui-glass ui-empty-state"><FileText size={24} className="ui-error-icon" /><h2>{title}</h2><p>{description}</p>{action}</section>; }
function ErrorState({ message, onRetry }: { message: string; onRetry?: () => void }) { return <section className="ui-glass ui-empty-state"><p className="ui-field-error">{message}</p>{onRetry && <button className="ui-button ui-button-ghost ui-button-sm" onClick={onRetry}><RefreshCw size={14} /> Retry</button>}</section>; }
function LoadingState({ label }: { label: string }) { return <section className="ui-glass ui-empty-state"><span className="ui-spinner" aria-hidden="true" /><p>{label}</p></section>; }
function Drawer({ title, subtitle, onClose, children, footer }: { title: string; subtitle?: ReactNode; onClose: () => void; children: ReactNode; footer?: ReactNode }) {
  return <SharedDrawer open title={title} description={subtitle} onClose={onClose} footer={footer}>{children}</SharedDrawer>;
}
function Dialog({ title, description, onClose, children, wide = false, busy = false }: { title: string; description?: string; onClose: () => void; children: ReactNode; wide?: boolean; busy?: boolean }) {
  return <SharedDialog open title={title} description={description} onClose={onClose} wide={wide} busy={busy}>{children}</SharedDialog>;
}
function DataTable({ children }: { children: ReactNode }) { return <section className="ui-glass ui-data-table"><div className="ui-data-scroll"><table>{children}</table></div></section>; }
function MetaGrid({ values }: { values: Array<[string, unknown]> }) { return <dl className="grid gap-x-5 gap-y-4 sm:grid-cols-2">{values.map(([label, value]) => <div key={label}><dt className="text-[13px] text-[var(--ui-muted)]">{label}</dt><dd className="mt-1 break-words text-sm text-[var(--ui-fg)]">{text(value)}</dd></div>)}</dl>; }
function Pagination({ page, loading, onPage }: { page: { limit: number; offset: number; total: number }; loading: boolean; onPage: (offset: number) => void }) { const from = page.total === 0 ? 0 : page.offset + 1; const to = Math.min(page.offset + page.limit, page.total); return <div className="ui-pagination"><span className="ui-pagination-count">{from}–{to} of {page.total.toLocaleString()} results</span><div className="ui-pagination-actions"><button className="ui-button ui-button-ghost ui-button-sm" disabled={loading || page.offset === 0} onClick={() => onPage(Math.max(0, page.offset - page.limit))}>Previous</button><button className="ui-button ui-button-ghost ui-button-sm" disabled={loading || page.offset + page.limit >= page.total} onClick={() => onPage(page.offset + page.limit)}>Next</button></div></div>; }
function FilterToolbar({ query, onQuery, filters, onFilter, onApply, activeCount, onClear, showQuery = true, children }: { query?: string; onQuery?: (value: string) => void; filters: DocumentFilters; onFilter: (key: FilterKey, value: string) => void; onApply: () => void; activeCount: number; onClear: () => void; showQuery?: boolean; children?: ReactNode }) { const [open, setOpen] = useState(false); const inline = ["sampleManagerVersion", "documentType"] as FilterKey[]; return <div className="space-y-3"><div className="flex flex-wrap items-center gap-3">{showQuery && onQuery && <label className="relative min-w-[280px] flex-1"><Search size={15} className="absolute left-3 top-3 text-[var(--ui-muted)]" /><input className="ui-control pl-9" placeholder="Search documents" value={query ?? ""} onChange={(event) => onQuery(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") onApply(); }} /></label>}{children}{inline.map((key) => <label key={key} className="ui-select-wrap w-40"><select className="ui-control" value={filters[key]} onChange={(event) => onFilter(key, event.target.value)}><option value="">{key === "sampleManagerVersion" ? "Version" : "Document type"}</option>{key === "documentType" && <><option value="markdown">Markdown</option><option value="html">HTML</option><option value="pdf">PDF</option><option value="zip">ZIP</option></>}{key === "sampleManagerVersion" && <option value={filters[key]}>{filters[key]}</option>}</select><ChevronDown size={15} className="ui-select-icon" /></label>)}<button className="ui-button ui-button-ghost ui-button-sm" onClick={() => setOpen(!open)}><SlidersHorizontal size={15} /> Filters {activeCount > 0 && <Badge tone="mint">{activeCount}</Badge>}</button><button className="ui-button ui-button-primary ui-button-sm" onClick={onApply}><Search size={14} /> Apply</button></div>{activeCount > 0 && <div className="flex flex-wrap items-center gap-2">{Object.entries(filters).filter(([, value]) => value).map(([key, value]) => <button key={key} className="ui-badge ui-badge-mint" onClick={() => onFilter(key as FilterKey, "")}>{key}: {value} <X size={12} /></button>)}<button className="ui-button ui-button-ghost ui-button-sm" onClick={onClear}>Clear all</button></div>}{open && <div className="ui-glass grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-4">{filterLabels.filter(([key]) => !inline.includes(key)).map(([key, label]) => <label className="ui-field" key={key}><span className="ui-field-label">{label}</span>{key === "status" ? <select className="ui-control" value={filters[key]} onChange={(event) => onFilter(key, event.target.value)}><option value="">Any status</option><option value="draft">Draft</option><option value="approved">Approved</option><option value="deprecated">Deprecated</option></select> : <input className="ui-control" value={filters[key]} placeholder={label} onChange={(event) => onFilter(key, event.target.value)} />}</label>)}<div className="flex items-end gap-2"><button className="ui-button ui-button-ghost ui-button-sm" onClick={onClear}>Reset</button><button className="ui-button ui-button-primary ui-button-sm" onClick={() => { setOpen(false); onApply(); }}>Apply filters</button></div></div>}</div>; }

function ProductDetail({ id, scope, onClose }: { id: string; scope: KnowledgeScope; onClose: () => void }) {
  const [data, setData] = useState<RecordValue>(); const [error, setError] = useState("");
  useEffect(() => { let cancelled = false; setData(undefined); setError(""); api.productDocumentGlobal(id, scope).then((result) => { if (!cancelled) setData(record(result)); }).catch((err: unknown) => { if (!cancelled) setError(err instanceof Error ? err.message : "Unable to load document"); }); return () => { cancelled = true; }; }, [id, scope.projectId, scope.environment]);
  const document = record(data?.document); const metadata = jsonObject(document.metadata); const sections = records(data?.sections); const title = text(document.title, "Product document");
  return <Drawer title={title} subtitle={<div className="mt-1 flex flex-wrap items-center gap-2"><Badge tone="iris">Product document</Badge><StatusPill value={document.lifecycle} /><code className="text-[13px] text-[var(--ui-muted)]">{id}</code></div>} onClose={onClose}>
    {error ? <ErrorState message={error} /> : !data ? <LoadingState label="Loading document and sections" /> : <div className="space-y-6"><div className="flex flex-wrap gap-2"><Link className="ui-button ui-button-ghost ui-button-sm" to={withKnowledgeScope(`/knowledge/product-docs/versions?document=${encodeURIComponent(id)}`, knowledgeItemScope(document, scope))}>Compare versions</Link><Link className="ui-button ui-button-ghost ui-button-sm" to={withKnowledgeScope(`/knowledge/product-docs/search?document=${encodeURIComponent(id)}`, knowledgeItemScope(document, scope))}>Search related sections</Link></div><section><h3 className="mb-4 text-[17px] font-semibold text-[var(--ui-fg)]">Overview</h3><MetaGrid values={[["Product", document.projectNameSnapshot], ["Version", document.sampleManagerVersion ?? document.version], ["Solution / module", [document.solution, document.module].filter(Boolean).join(" / ")], ["Type / language", [document.documentType, document.language].filter(Boolean).join(" / ")], ["Environment", document.environment ?? scope.environment ?? "Default"], ["Authority", document.authority], ["Source path", document.sourcePath ?? document.sourceLocator], ["Git commit", document.sourceCommit], ["Parser version", document.parserVersion ?? metadata.parserVersion], ["Topic / family", document.topicId ?? document.documentFamilyId], ["Source SHA-256", document.sourceSha256 ?? metadata.sourceHash], ["Indexed", formatDate(document.lastIndexedAt ?? document.updatedAt)]]} /></section><section><h3 className="mb-3 text-[17px] font-semibold text-[var(--ui-fg)]">Inference and provenance</h3><div className="flex flex-wrap gap-2"><Badge tone="iris">Confidence {metadata.confidence === undefined ? "Not scored" : `${Math.round(numberValue(metadata.confidence) * 100)}%`}</Badge>{records(metadata.reasons).map((reason, index) => <Badge key={index}>{text(reason)}</Badge>)}</div><p className="mt-3 text-sm leading-6 text-[var(--ui-muted)]">Source hashes, import audit, lifecycle and version metadata identify this document in the selected scope.</p></section><section><h3 className="mb-3 text-[17px] font-semibold text-[var(--ui-fg)]">Document content</h3><KnowledgeMarkup source={text(document.body, "")} /></section><section><h3 className="mb-3 text-[17px] font-semibold text-[var(--ui-fg)]">Source sections and chunks</h3>{sections.length === 0 ? <p className="text-sm text-[var(--ui-muted)]">No document sections were returned.</p> : <div className="space-y-3">{sections.map((section, index) => <details key={text(section.key, String(index))} className="ui-glass p-3"><summary className="cursor-pointer text-sm text-[var(--ui-fg)]">{text(section.path ?? section.title, "Untitled section")}</summary><pre className="mt-3 max-h-96 overflow-auto whitespace-pre-wrap break-words text-xs leading-6 text-[var(--ui-muted)]">{text(section.text, "(empty section)")}</pre><p className="mt-3 break-all text-[11px] text-[var(--ui-muted)]">Stable key: {text(section.key)} · anchor: {text(section.anchor, "unavailable")}{section.chunkId ? ` · chunk: ${text(section.chunkId)}` : ""}</p></details>)}</div>}</section></div>}
  </Drawer>;
}

function ProductList({ scope, selectedId, onSelect, onImport }: { scope: KnowledgeScope; selectedId: string; onSelect: (id: string, sourceScope: KnowledgeScope) => void; onImport?: () => void }) {
  const [params, setParams] = useSearchParams(); const [docs, setDocs] = useState<DocumentRecord[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [refresh, setRefresh] = useState(0); const requestSequence = useRef(0);
  const appliedFilters = useMemo(() => filterLabels.reduce((result, [key]) => ({ ...result, [key]: params.get(key) ?? "" }), {} as DocumentFilters), [params]); const [filters, setFilters] = useState<DocumentFilters>(appliedFilters); const query = params.get("q") ?? ""; const offset = Math.max(0, Math.trunc(numberValue(params.get("offset")))); const [page, setPage] = useState({ limit: 25, offset, total: 0 });
  const load = (nextOffset = offset, applyDraft = false) => { const next = new URLSearchParams(params); const values = applyDraft ? filters : appliedFilters; Object.entries(values).forEach(([key, value]) => value ? next.set(key, value) : next.delete(key)); query ? next.set("q", query) : next.delete("q"); nextOffset ? next.set("offset", String(nextOffset)) : next.delete("offset"); setParams(next, { replace: true }); setRefresh((value) => value + 1); };
  useEffect(() => { setFilters(appliedFilters); const requestId = ++requestSequence.current; setLoading(true); setError(""); api.productDocumentsList({ ...appliedFilters, q: query || undefined, ...buildKnowledgeScope(scope), limit: 25, offset }).then((result) => { if (requestId !== requestSequence.current) return; const response = record(result); setDocs(records(response.documents)); const resultPage = record(response.page); setPage({ limit: numberValue(resultPage.limit, 25), offset: numberValue(resultPage.offset, offset), total: numberValue(resultPage.total, records(response.documents).length) }); }).catch((err: unknown) => { if (requestId === requestSequence.current) setError(err instanceof Error ? err.message : "Unable to load product documents"); }).finally(() => { if (requestId === requestSequence.current) setLoading(false); }); return () => { requestSequence.current++; }; }, [scope.projectId, scope.environment, JSON.stringify(appliedFilters), query, offset, refresh]);
  const activeCount = Object.values(filters).filter(Boolean).length + (query ? 1 : 0); const applyFilter = (key: FilterKey, value: string) => setFilters((old) => ({ ...old, [key]: value })); const clear = () => { setFilters(emptyFilters); setParams((current) => { const next = new URLSearchParams(current); filterLabels.forEach(([key]) => next.delete(key)); next.delete("q"); next.delete("offset"); return next; }, { replace: true }); setRefresh((value) => value + 1); };
  return <div className="space-y-4"><FilterToolbar query={query} onQuery={(value) => setParams((current) => { const next = new URLSearchParams(current); value ? next.set("q", value) : next.delete("q"); next.delete("offset"); return next; }, { replace: true })} filters={filters} onFilter={applyFilter} onApply={() => load(0, true)} activeCount={activeCount} onClear={clear} /><div className="flex justify-end text-[13px] text-[var(--ui-muted)]"><span className="font-mono">{page.total.toLocaleString()}</span>&nbsp;results</div>{loading ? <LoadingState label="Loading product documents" /> : error ? <ErrorState message={error} onRetry={() => load(offset)} /> : docs.length === 0 ? <EmptyState title="No product documents found" description="Import a source batch or clear a filter to broaden the results." action={onImport ? <button className="ui-button ui-button-primary ui-button-sm" onClick={onImport}><Import size={14} /> Import documents</button> : undefined} /> : <><DataTable><thead><tr><th>Title</th><th>Version</th><th>Type</th><th>Language</th><th>Authority</th><th>Updated</th><th /></tr></thead><tbody>{docs.map((doc) => { const id = text(doc.id); return <tr key={id} className={`ui-data-row-clickable ${id === selectedId ? "ui-data-row-selected" : ""}`} onClick={() => onSelect(id, knowledgeItemScope(doc, scope))}><td><p className="font-medium">{text(doc.title)}</p><p className="mt-1 max-w-[320px] truncate text-xs text-[var(--ui-muted)]">{text(doc.sourcePath ?? doc.sourceLocator)}</p></td><td>{text(doc.sampleManagerVersion ?? doc.version)}</td><td>{text(doc.documentType)}</td><td>{text(doc.language)}</td><td><Badge tone="neutral">{text(doc.authority)}</Badge></td><td><StatusPill value={doc.lifecycle} /><span className="mt-1 block text-xs text-[var(--ui-muted)]">{formatDate(doc.updatedAt)}</span></td><td><ChevronRight size={16} className="text-[var(--ui-muted)]" /></td></tr>; })}</tbody></DataTable><Pagination page={page} loading={loading} onPage={(nextOffset) => load(nextOffset)} /></>}</div>;
}

function ImportDialog({ scope, onClose, onComplete }: { scope: KnowledgeScope; onClose: () => void; onComplete: () => void }) {
  const { projects: contextProjects, projectId: contextProjectId } = useProjectScope();
  const projects: ProjectRecord[] = contextProjects;
  const { success } = useToast();
  const completeRef = useRef(onComplete); completeRef.current = onComplete;
  const successRef = useRef(success); successRef.current = success;
  const [projectId, setProjectId] = useState<number>();
  const [path, setPath] = useState("knowledge/product-docs"); const [version, setVersion] = useState(""); const [product, setProduct] = useState(""); const [solution, setSolution] = useState(""); const [moduleName, setModuleName] = useState(""); const [language, setLanguage] = useState("en"); const [authority, setAuthority] = useState("official"); const [files, setFiles] = useState<File[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [stage, setStage] = useState<ImportStage>("idle"); const [progress, setProgress] = useState(0); const [activeJob, setActiveJob] = useState<string | null>(() => localStorage.getItem("product-import-job")); const [jobProgress, setJobProgress] = useState<RecordValue>(); const [report, setReport] = useState<RecordValue>();
  useEffect(() => { const scoped = scope.projectId ? numberValue(scope.projectId) : contextProjectId; const next = scoped && projects.some((project) => project.id === scoped) ? scoped : projects[0]?.id; setProjectId((current) => current === next ? current : next); }, [contextProjectId, projects, scope.projectId]);
  useEffect(() => { if (!activeJob) return; let cancelled = false; const poll = async () => { setStage("processing"); while (!cancelled) { try { const result = record(await api.knowledgeIngestJob(activeJob)); if (cancelled) return; const job = record(result.job); const jobResult = record(job.result); setJobProgress(jobResult); if (numberValue(jobResult.total) > 0) setProgress(Math.min(99, 50 + Math.round(49 * numberValue(jobResult.processed) / numberValue(jobResult.total)))); const state = text(job.status); if (state === "succeeded" || state === "failed") { setReport({ ...jobResult, status: state }); setStage(state); setProgress(100); localStorage.removeItem("product-import-job"); setActiveJob(null); window.dispatchEvent(new Event("product-import-completed")); if (state === "failed") { setError(text(job.error ?? (Array.isArray(jobResult.warnings) ? jobResult.warnings.join("; ") : undefined), "Import failed. See import history for details.")); } else { successRef.current("Product documents imported."); completeRef.current(); } return; } } catch (err: unknown) { if (!cancelled) setError(`Unable to read import status: ${err instanceof Error ? err.message : "connection error"}. The import may still be running.`); } await new Promise((resolve) => setTimeout(resolve, 2000)); } }; void poll(); return () => { cancelled = true; }; }, [activeJob]);
  const uploadFile = async (file: File, selectedProjectId: number): Promise<string> => {
    const token = localStorage.getItem("token");
    const workspacePath = path.trim().replace(/\/+$/, "");
    if (!workspacePath) throw new Error("Enter a workspace folder before uploading files.");
    const sessionResponse = await fetch(`/api/projects/${selectedProjectId}/uploads`, {
      method: "POST",
      headers: { "Content-Type": "application/json", ...(token ? { Authorization: `Bearer ${token}` } : {}) },
      body: JSON.stringify({ path: `${workspacePath}/${file.name}` }),
    });
    if (!sessionResponse.ok) {
      const sessionError = record(await sessionResponse.json().catch(() => ({})));
      throw new Error(text(sessionError.error, "Unable to create upload session"));
    }
    const created = record(await sessionResponse.json());
    const upload = record(created.upload);
    const uploadUrl = text(created.uploadUrl, "");
    const uploadToken = text(created.token, "");
    if (!uploadToken || !uploadUrl) throw new Error("Upload session response is incomplete");
    const uploadResponse = await fetch(uploadUrl, {
      method: "PUT",
      headers: { "Content-Type": "application/octet-stream", "X-Relay-Upload-Token": uploadToken },
      body: file,
    });
    if (!uploadResponse.ok) {
      const uploadError = record(await uploadResponse.json().catch(() => ({})));
      throw new Error(text(uploadError.error, "Upload failed"));
    }
    return text(upload.path);
  };
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!files.length || !version.trim() || !projectId) { setError(!files.length ? "Choose at least one file to import." : !projectId ? "Select a project before uploading files." : "Enter the SampleManager version."); return; } if (!path.trim()) { setError("Enter a workspace folder before uploading files."); return; } setBusy(true); setError(""); setReport(undefined); setProgress(5); try { setStage("uploading"); const uploaded: string[] = []; for (let index = 0; index < files.length; index += 1) { uploaded.push(await uploadFile(files[index], projectId)); setProgress(10 + Math.round(((index + 1) / files.length) * 35)); } const importScope: RecordValue = uploaded.length === 1 ? { projectId, path: uploaded[0] } : { projectId, path: path.trim().replace(/\/+$/, "") }; setStage("queued"); setProgress(50); const initial = record(await api.productDocumentImportGlobal({ ...importScope, sampleManagerVersion: version, product: product || undefined, solution: solution || undefined, module: moduleName || undefined, language: language || undefined, authority: authority || undefined }, `product-import:${Date.now()}`)); const id = text(initial.id, ""); if (id) { localStorage.setItem("product-import-job", id); setActiveJob(id); setStage("processing"); } else { setReport(initial); setProgress(100); setStage(text(initial.status, "succeeded") as ImportStage); success("Product documents imported."); onComplete(); } } catch (err: unknown) { setError(err instanceof Error ? err.message : "Product import failed"); setStage("failed"); setProgress(100); } finally { setBusy(false); } };
  const stageLabel = stage === "uploading" ? "Uploading files" : stage === "queued" ? "Queueing import" : stage === "processing" ? "Extracting, indexing and validating" : stage === "succeeded" ? "Import completed" : stage === "failed" ? "Import failed" : "";
  return <Dialog title="Import documents" description="Add versioned Markdown, HTML, PDF or ZIP sources." onClose={onClose} wide><form onSubmit={submit} className="space-y-4"><label className="ui-field"><span className="ui-field-label">Project</span><select className="ui-control" value={projectId ?? ""} onChange={(event) => setProjectId(event.target.value ? Number(event.target.value) : undefined)} required><option value="">Select a project</option>{projects.map((project) => <option key={project.id} value={project.id}>{text(project.name ?? project.id)}</option>)}</select></label><label className="ui-field"><span className="ui-field-label">Files</span><span className="ui-dropzone"><UploadCloud size={22} /><span>Drop documents here or choose files</span><span className="text-xs">.md, .markdown, .html, .htm, .pdf, .zip</span><input type="file" multiple accept=".md,.markdown,.html,.htm,.pdf,.zip" onChange={(event) => setFiles(Array.from(event.target.files ?? []))} /></span>{files.length > 0 && <span className="ui-field-hint">{files.length} file(s) staged through the selected project workspace.</span>}</label><label className="ui-field"><span className="ui-field-label">SampleManager version</span><input className="ui-control" required value={version} onChange={(event) => setVersion(event.target.value)} /></label><label className="ui-field"><span className="ui-field-label">Product</span><input className="ui-control" value={product} onChange={(event) => setProduct(event.target.value)} /></label><label className="ui-field"><span className="ui-field-label">Workspace folder</span><input className="ui-control" value={path} onChange={(event) => setPath(event.target.value)} /></label><details><summary className="cursor-pointer text-sm text-[var(--ui-fg)]">Advanced</summary><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="ui-field"><span className="ui-field-label">Solution</span><input className="ui-control" value={solution} onChange={(event) => setSolution(event.target.value)} /></label><label className="ui-field"><span className="ui-field-label">Module</span><input className="ui-control" value={moduleName} onChange={(event) => setModuleName(event.target.value)} /></label><label className="ui-field"><span className="ui-field-label">Language</span><input className="ui-control" value={language} onChange={(event) => setLanguage(event.target.value)} /></label><label className="ui-field"><span className="ui-field-label">Authority</span><input className="ui-control" value={authority} onChange={(event) => setAuthority(event.target.value)} /></label></div></details>{(busy || activeJob || report) && <div className="ui-glass p-3"><div className="flex items-center justify-between text-sm"><span>{stageLabel}{jobProgress ? ` ${numberValue(jobProgress.processed).toLocaleString()} / ${numberValue(jobProgress.total).toLocaleString()} documents` : ""}</span><span>{progress}%</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-white/10"><div className="h-full bg-[var(--ui-mint)] transition-all" style={{ width: `${progress}%` }} /></div>{report && <p className="mt-2 text-xs text-[var(--ui-muted)]">{numberValue(report.imported)} added, {numberValue(report.updated)} updated, {numberValue(report.unchanged)} unchanged, {numberValue(report.failed)} failed.</p>}</div>}{error && <p className="ui-dialog-error">{error}</p>}<div className="ui-dialog-footer"><button type="button" className="ui-button ui-button-ghost" onClick={onClose}>Cancel</button><button type="submit" className="ui-button ui-button-primary" disabled={busy || Boolean(activeJob)}><Import size={15} />{busy || activeJob ? stageLabel : "Import documents"}</button></div></form></Dialog>;
}

function ProductImportRuns({ onImport, onSelectRun }: { onImport: () => void; onSelectRun: (id: string) => void }) {
  const [runs, setRuns] = useState<ImportRunRecord[]>([]); const [error, setError] = useState("");
  const load = () => api.productDocumentImports(100).then((result) => setRuns(records(record(result).runs))).catch((err: unknown) => setError(err instanceof Error ? err.message : "Unable to load import runs")); useEffect(() => { load(); const handler = () => load(); window.addEventListener("product-import-completed", handler); return () => window.removeEventListener("product-import-completed", handler); }, []);
  return <div className="space-y-4"><div className="flex justify-end"><button className="ui-button ui-button-primary" onClick={onImport}><Import size={15} /> Import documents</button></div>{error && <ErrorState message={error} onRetry={load} />}{runs.length === 0 ? <EmptyState title="No import runs yet" description="Import product documents to start one." action={<button className="ui-button ui-button-primary ui-button-sm" onClick={onImport}><Import size={14} /> Import documents</button>} /> : <DataTable><thead><tr><th>Source</th><th>Started</th><th>Counts</th><th>Status</th><th /></tr></thead><tbody>{runs.map((run) => { const id = text(run.id); return <tr key={id} className="ui-data-row-clickable" onClick={() => onSelectRun(id)}><td><p className="font-medium">{text(run.source_locator ?? id)}</p><p className="mt-1 text-xs text-[var(--ui-muted)]">{text(run.source_commit ?? run.source_sha256)}</p></td><td>{formatDate(run.started_at)}</td><td>{numberValue(run.imported)} imported, {numberValue(run.skipped)} unchanged, {numberValue(run.failed)} failed</td><td><StatusPill value={run.status} /></td><td><ChevronRight size={16} /></td></tr>; })}</tbody></DataTable>}</div>;
}
function ProductTopics({ scope, selectedId, onSelect }: { scope: KnowledgeScope; selectedId: string; onSelect: (id: string) => void }) {
  const [params, setParams] = useSearchParams();
  const [topics, setTopics] = useState<TopicRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const query = params.get("q") ?? "";
  const status = params.get("status") ?? "";
  const offset = Math.max(0, Math.trunc(numberValue(params.get("offset"))));
  const [draftQuery, setDraftQuery] = useState(query);
  const [draftStatus, setDraftStatus] = useState(status);
  const [page, setPage] = useState({ limit: 25, offset, total: 0 });
  const load = (nextOffset = offset, nextQuery = query, nextStatus = status) => {
    const next = new URLSearchParams(params);
    nextQuery.trim() ? next.set("q", nextQuery.trim()) : next.delete("q");
    nextStatus ? next.set("status", nextStatus) : next.delete("status");
    nextOffset ? next.set("offset", String(nextOffset)) : next.delete("offset");
    setParams(next, { replace: true });
  };
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError("");
    api.productTopics({ ...buildKnowledgeScope(scope), q: query || undefined, status: status || undefined, limit: 25, offset })
      .then((result) => {
        if (cancelled) return;
        const response = record(result);
        const rows = records(response.topics);
        const resultPage = record(response.page);
        setTopics(rows);
        setPage({ limit: numberValue(resultPage.limit, 25), offset: numberValue(resultPage.offset, offset), total: numberValue(resultPage.total, rows.length) });
      })
      .catch((err: unknown) => { if (!cancelled) setError(err instanceof Error ? err.message : "Unable to load logical topics"); })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [scope.projectId, scope.environment, query, status, offset]);
  useEffect(() => { setDraftQuery(query); setDraftStatus(status); }, [query, status]);
  return <div className="space-y-4">
    <div className="flex flex-wrap items-end gap-3">
      <label className="ui-field min-w-[240px] flex-1"><span className="ui-field-label">Search topics</span><input className="ui-control" value={draftQuery} onChange={(event) => setDraftQuery(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") load(0, draftQuery, draftStatus); }} placeholder="Canonical title or topic ID" /></label>
      <label className="ui-field w-44"><span className="ui-field-label">Binding status</span><select className="ui-control" value={draftStatus} onChange={(event) => setDraftStatus(event.target.value)}><option value="">Any status</option><option value="active">Active</option><option value="pending_review">Pending review</option><option value="rejected">Rejected</option></select></label>
      <button className="ui-button ui-button-primary" onClick={() => load(0, draftQuery, draftStatus)}><Search size={14} /> Apply</button>
    </div>
    {loading ? <LoadingState label="Loading logical topics" /> : error ? <ErrorState message={error} onRetry={() => load()} /> : topics.length === 0 ? <EmptyState title="No logical topics found" description="Import product documents to create canonical topics." /> : <DataTable><thead><tr><th>Topic</th><th>Product</th><th>Versions</th><th>Latest status</th><th>Updated</th><th /></tr></thead><tbody>{topics.map((topic, index) => { const id = text(topic.id, String(index)); return <tr key={id} className={`ui-data-row-clickable ${selectedId === id ? "ui-data-row-selected" : ""}`} onClick={() => onSelect(id)}><td><p className="font-medium">{text(topic.canonical_title ?? topic.title, "Untitled topic")}</p><code className="mt-1 block text-xs text-[var(--ui-muted)]">{id}</code></td><td>{text(topic.product ?? topic.product_name)}</td><td>{numberValue(topic.version_count ?? topic.versions)}</td><td><StatusPill value={topic.status ?? topic.latest_status ?? "active"} /></td><td>{formatDate(topic.updated_at ?? topic.updatedAt)}</td><td><ChevronRight size={16} className="text-[var(--ui-muted)]" /></td></tr>; })}</tbody></DataTable>}
    {!loading && !error && topics.length > 0 && <Pagination page={page} loading={loading} onPage={(nextOffset) => load(nextOffset, query, status)} />}
    {selectedId && <TopicDrawer topic={topics.find((topic) => text(topic.id) === selectedId) ?? { id: selectedId }} scope={scope} onClose={() => onSelect("")} />}
  </div>;
}


function ImportRunDrawer({ run, onClose, onRefresh }: { run: ImportRunRecord; onClose: () => void; onRefresh: () => void }) { const [selectedIds, setSelectedIds] = useState<string[]>([]); const [correction, setCorrection] = useState({ module: "", documentType: "", language: "", authority: "", reason: "" }); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const detail = record(run); const runDetails = record(detail.run); const items = records(detail.items); const low = items.filter((item) => numberValue(jsonObject(item.metadata_json).confidence, 1) < 0.7); const correct = async () => { if (!selectedIds.length || !correction.reason.trim()) { setError("Select low-confidence items and enter a correction reason."); return; } setBusy(true); setError(""); try { await api.productDocumentMetadataCorrection({ ids: selectedIds, module: correction.module || undefined, documentType: correction.documentType || undefined, language: correction.language || undefined, authority: correction.authority || undefined, reason: correction.reason }, `product-metadata-correction:${text(runDetails.id)}:${selectedIds.join(",")}:${Date.now()}`); onRefresh(); setSelectedIds([]); } catch (err: unknown) { setError(err instanceof Error ? err.message : "Metadata correction failed"); } finally { setBusy(false); } }; return <Drawer title={text(runDetails.source_locator ?? runDetails.id, "Import run")} subtitle={<div className="mt-1"><StatusPill value={runDetails.status} /></div>} onClose={onClose}><div className="space-y-5"><MetaGrid values={[["Run", runDetails.id], ["Source commit / hash", [runDetails.source_commit, runDetails.source_sha256].filter(Boolean).join(" / ")], ["Started", formatDate(runDetails.started_at)]]} /><div className="space-y-2">{items.map((item, index) => { const metadata = jsonObject(item.metadata_json); const itemId = text(item.document_id ?? item.id ?? index); const isLow = numberValue(metadata.confidence, 1) < 0.7; const reasons = Array.isArray(metadata.reasons) ? metadata.reasons.map((reason: unknown) => text(reason)).join("; ") : ""; return <label key={itemId} className={`block rounded-lg border p-3 text-xs ${isLow ? "border-[rgba(255,180,84,.4)]" : "border-[var(--ui-line)]"}`}><span className="flex items-center justify-between gap-2"><span className="flex min-w-0 items-center gap-2"><input type="checkbox" disabled={!isLow} checked={selectedIds.includes(itemId)} onChange={(event) => setSelectedIds((ids) => event.target.checked ? [...new Set([...ids, itemId])] : ids.filter((id) => id !== itemId))} /><span className="break-all">{text(item.relative_path)}</span></span><StatusPill value={item.status} /></span>{metadata.confidence !== undefined && <span className="mt-2 block text-[var(--ui-muted)]">Inference confidence {Math.round(numberValue(metadata.confidence) * 100)}% · {reasons}</span>}{Boolean(item.warning || item.error) && <span className="mt-2 block text-[var(--ui-coral)]">{text(item.warning ?? item.error)}</span>}</label>; })}</div>{low.length > 0 && <section className="ui-glass p-3"><h3 className="text-sm font-medium">Batch-correct low-confidence metadata ({selectedIds.length}/{low.length} selected)</h3><div className="mt-3 grid gap-2 sm:grid-cols-2">{(["module", "documentType", "language", "authority"] as const).map((key) => <input key={key} className="ui-control" placeholder={`${key} correction`} value={correction[key]} onChange={(event) => setCorrection({ ...correction, [key]: event.target.value })} />)}</div><textarea className="ui-control mt-2" placeholder="Correction reason (required for audit)" value={correction.reason} onChange={(event) => setCorrection({ ...correction, reason: event.target.value })} /><button disabled={busy || !selectedIds.length} className="ui-button ui-button-accent ui-button-sm mt-2" onClick={() => void correct()}>{busy ? "Saving" : "Apply batch correction"}</button></section>}{text(runDetails.status) === "failed" && <button className="ui-button ui-button-accent" onClick={async () => { try { await api.productDocumentRetry(text(runDetails.id), `product-retry:${text(runDetails.id)}:${Date.now()}`); onRefresh(); } catch (err: unknown) { setError(err instanceof Error ? err.message : "Retry failed"); } }}><RefreshCw size={14} /> Retry failed</button>}{error && <p className="ui-field-error">{error}</p>}</div></Drawer>; }
function TopicDrawer({ topic, scope, onClose }: { topic: TopicRecord; scope: KnowledgeScope; onClose: () => void }) { const [detail, setDetail] = useState<RecordValue>(); const [error, setError] = useState(""); const [reasons, setReasons] = useState<Record<string, string>>({}); useEffect(() => { api.productTopic(text(topic.id), scope).then((result) => setDetail(record(result))).catch((err: unknown) => setError(err instanceof Error ? err.message : "Unable to load topic")); }, [topic.id, scope.projectId, scope.environment]); const versions = records(detail?.versions); const review = async (id: string, status: "active" | "rejected") => { const reason = (reasons[id] ?? "").trim(); if (!reason) { setError("Enter a review reason before approving or rejecting the binding."); return; } try { await api.productTopicBindingReview(id, { status, reason }); setReasons((old) => ({ ...old, [id]: "" })); const refreshed = await api.productTopic(text(topic.id), scope); setDetail(record(refreshed)); } catch (err: unknown) { setError(err instanceof Error ? err.message : "Binding review failed"); } }; return <Drawer title={text(topic.canonical_title, "Logical topic")} subtitle={<div className="mt-1"><Badge tone="iris">Logical topic</Badge><code className="ml-2 text-[13px] text-[var(--ui-muted)]">{text(topic.id)}</code></div>} onClose={onClose}>{error && <p className="ui-field-error mb-4">{error}</p>}{!detail ? <LoadingState label="Loading topic details" /> : <div className="space-y-3">{versions.map((row) => <details key={text(row.id)} className="ui-glass p-3"><summary className="cursor-pointer text-sm"><span className="mr-3 text-[var(--ui-mint)]">{text(row.product_version)}</span>{text(row.title)} <StatusPill value={row.status ?? "active"} /></summary><MetaGrid values={[["Source", row.source_path], ["Revision hash", row.source_sha256], ["Document ID", row.document_id], ["Sections", Array.isArray(row.sections) ? row.sections.length : 0], ["Match", `${text(row.match_method)} · ${Math.round(numberValue(row.match_confidence) * 100)}%`]]} />{text(row.status) === "pending_review" && <div className="mt-3 space-y-2"><input className="ui-control" placeholder="Binding review reason (required)" value={reasons[text(row.id)] ?? ""} onChange={(event) => setReasons((old) => ({ ...old, [text(row.id)]: event.target.value }))} /><div className="flex gap-2"><button className="ui-button ui-button-primary ui-button-sm" disabled={!(reasons[text(row.id)] ?? "").trim()} onClick={() => void review(text(row.id), "active")}>Approve</button><button className="ui-button ui-button-danger ui-button-sm" disabled={!(reasons[text(row.id)] ?? "").trim()} onClick={() => void review(text(row.id), "rejected")}>Reject</button></div></div>}<p className="mt-3 whitespace-pre-wrap text-sm leading-6 text-[var(--ui-muted)]">{text(row.body, "")}</p></details>)}</div>}</Drawer>; }

function ProductVersions({ scope, groupId, onSelect }: { scope: KnowledgeScope; groupId: string; onSelect: (id: string) => void }) { const [params, setParams] = useSearchParams(); const [rows, setRows] = useState<VersionRecord[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [family, setFamily] = useState(params.get("family") ?? ""); const [version, setVersion] = useState(params.get("version") ?? ""); const [left, setLeft] = useState(params.get("left") ?? ""); const [right, setRight] = useState(params.get("right") ?? ""); const [docs, setDocs] = useState<DocumentRecord[]>([]); const [diff, setDiff] = useState<DiffRecord>(); const [reviewStatus, setReviewStatus] = useState<"accepted" | "rejected" | "needs_review">("needs_review"); const [reviewReason, setReviewReason] = useState(""); const [busy, setBusy] = useState(false); const load = () => { setLoading(true); api.productDocumentVersions({ ...buildKnowledgeScope(scope), limit: 25, offset: numberValue(params.get("offset")) }).then((result) => setRows(records(record(result).versions))).catch((err: unknown) => setError(err instanceof Error ? err.message : "Unable to load versions")).finally(() => setLoading(false)); }; useEffect(() => { load(); }, [scope.projectId, scope.environment]); const loadDocuments = async () => { if (!family.trim() && !version.trim()) { setError("Enter a document family or version before loading revision documents."); return; } setError(""); const next = new URLSearchParams(params); family.trim() ? next.set("family", family.trim()) : next.delete("family"); version.trim() ? next.set("version", version.trim()) : next.delete("version"); setParams(next, { replace: true }); try { const result = await api.productDocumentsList({ ...buildKnowledgeScope(scope), documentFamilyId: family.trim() || undefined, sampleManagerVersion: version.trim() || undefined, includeDeprecated: "true", limit: 500, offset: 0 }); setDocs(records(record(result).documents)); } catch (err: unknown) { setError(err instanceof Error ? err.message : "Unable to load revision documents"); } }; const compare = async () => { if (!left || !right || left === right) return; setError(""); const next = new URLSearchParams(params); next.set("left", left); next.set("right", right); next.set("diff", "1"); setParams(next, { replace: true }); try { const result = record(await api.productDocumentDiffs(left, right)); setDiff(record(result.diff ?? records(result.diffs)[0]?.report ?? result.report ?? result) as DiffRecord); } catch (err: unknown) { setError(err instanceof Error ? err.message : "Diff failed"); } }; const current = rows.find((row) => `${text(row.document_family_id)}:${text(row.version)}` === groupId); return <div className="space-y-4">{loading ? <LoadingState label="Loading version groups" /> : error && rows.length === 0 ? <ErrorState message={error} onRetry={load} /> : <><div className="flex flex-wrap items-end gap-3"><label className="ui-field min-w-[220px] flex-1"><span className="ui-field-label">Document family</span><input className="ui-control" value={family} onChange={(event) => setFamily(event.target.value)} /></label><label className="ui-field w-40"><span className="ui-field-label">Version</span><input className="ui-control" value={version} onChange={(event) => setVersion(event.target.value)} /></label><button className="ui-button ui-button-ghost" onClick={() => void loadDocuments()}>Load documents</button></div>{error && <p className="ui-field-error">{error}</p>}<DataTable><thead><tr><th>Document family</th><th>Version</th><th>Documents</th><th>Updated</th><th /></tr></thead><tbody>{rows.map((row) => { const id = `${text(row.document_family_id)}:${text(row.version)}`; return <tr key={id} className={`ui-data-row-clickable ${id === groupId ? "ui-data-row-selected" : ""}`} onClick={() => onSelect(id)}><td>{text(row.document_family_id)}</td><td>{text(row.version)}</td><td>{numberValue(row.documents).toLocaleString()}</td><td>{formatDate(row.updated_at)}</td><td><ChevronRight size={16} /></td></tr>; })}</tbody></DataTable><div className="ui-pagination"><span>{rows.length.toLocaleString()} groups loaded</span></div>{current && <VersionDrawer group={current} docs={docs} left={left} right={right} setLeft={setLeft} setRight={setRight} compare={compare} diff={diff} reviewStatus={reviewStatus} setReviewStatus={setReviewStatus} reviewReason={reviewReason} setReviewReason={setReviewReason} busy={busy} review={async () => { if (!diff?.rightId || !diff.leftId || !reviewReason.trim()) { setError("A review reason is required."); return; } setBusy(true); try { await api.productDocumentDiffReview(diff.rightId, { against: diff.leftId, status: reviewStatus, reason: reviewReason }, `product-diff-review:${diff.rightId}:${diff.leftId}:${Date.now()}`); setDiff({ ...diff, reviewStatus }); setReviewReason(""); } catch (err: unknown) { setError(err instanceof Error ? err.message : "Diff review failed"); } finally { setBusy(false); } }} onClose={() => onSelect("")} />}</>}</div>; }
function VersionDrawer({ group, docs, left, right, setLeft, setRight, compare, diff, reviewStatus, setReviewStatus, reviewReason, setReviewReason, busy, review, onClose }: { group: VersionRecord; docs: DocumentRecord[]; left: string; right: string; setLeft: (value: string) => void; setRight: (value: string) => void; compare: () => Promise<void>; diff?: DiffRecord; reviewStatus: "accepted" | "rejected" | "needs_review"; setReviewStatus: (value: "accepted" | "rejected" | "needs_review") => void; reviewReason: string; setReviewReason: (value: string) => void; busy: boolean; review: () => Promise<void>; onClose: () => void }) { const changes = records(diff?.changes); return <Drawer title={`${text(group.document_family_id)} · ${text(group.version)}`} subtitle={<div className="mt-1"><Badge tone="iris">Version group</Badge></div>} onClose={onClose}><div className="space-y-5"><div className="grid gap-3 sm:grid-cols-2"><label className="ui-field"><span className="ui-field-label">Base document</span><select className="ui-control" value={left} onChange={(event) => setLeft(event.target.value)}><option value="">Select base</option>{docs.map((doc) => <option key={`left-${text(doc.id)}`} value={text(doc.id)}>{text(doc.title)} · {text(doc.sampleManagerVersion ?? doc.version)}</option>)}</select></label><label className="ui-field"><span className="ui-field-label">Target document</span><select className="ui-control" value={right} onChange={(event) => setRight(event.target.value)}><option value="">Select target</option>{docs.map((doc) => <option key={`right-${text(doc.id)}`} value={text(doc.id)}>{text(doc.title)} · {text(doc.sampleManagerVersion ?? doc.version)}</option>)}</select></label></div><button className="ui-button ui-button-primary" disabled={!left || !right || left === right} onClick={() => void compare()}><GitCompare size={15} /> Compare revisions</button>{diff && <section className="space-y-4"><div className="flex items-center justify-between"><h3 className="text-[17px] font-semibold">Diff result</h3><StatusPill value={diff.reviewStatus ?? "needs_review"} /></div><div className="grid grid-cols-2 gap-2 sm:grid-cols-3">{["unchanged", "added", "removed", "modified", "moved", "renamed"].map((state) => <div className="ui-glass p-3" key={state}><p className="text-xs text-[var(--ui-muted)]">{state}</p><p className="mt-1 text-lg font-semibold">{changes.filter((change) => text(change.status) === state).length}</p></div>)}</div>{changes.length === 0 ? <p className="text-sm text-[var(--ui-muted)]">No section-level changes were detected.</p> : changes.map((change, index) => <details className="ui-glass p-3" key={text(change.key, String(index))}><summary className="cursor-pointer text-sm">{text(change.status)} · {text(change.path ?? change.key)}</summary><div className="mt-3 grid gap-3 md:grid-cols-2"><pre className="max-h-60 overflow-auto whitespace-pre-wrap break-words rounded-lg bg-[rgba(255,122,112,.08)] p-3 text-xs">{JSON.stringify(change.left ?? "(not present)", null, 2)}</pre><pre className="max-h-60 overflow-auto whitespace-pre-wrap break-words rounded-lg bg-[rgba(110,231,200,.08)] p-3 text-xs">{JSON.stringify(change.right ?? "(not present)", null, 2)}</pre></div>{Array.isArray(change.textDiff) && <p className="mt-3 whitespace-pre-wrap text-xs text-[var(--ui-muted)]">{records(change.textDiff).map((part) => text(part.value)).join("")}</p>}</details>)}<div className="border-t border-[var(--ui-line)] pt-4"><div className="grid gap-2"><select className="ui-control" value={reviewStatus} onChange={(event) => setReviewStatus(event.target.value as "accepted" | "rejected" | "needs_review")}><option value="accepted">Accept</option><option value="rejected">Reject</option><option value="needs_review">Needs review</option></select><textarea className="ui-control" placeholder="Review reason (required)" value={reviewReason} onChange={(event) => setReviewReason(event.target.value)} /><button className="ui-button ui-button-accent" disabled={busy || !reviewReason.trim()} onClick={() => void review()}>{busy ? "Saving" : "Save review"}</button></div></div></section>}</div></Drawer>; }

function ProductSearch({ scope }: { scope: KnowledgeScope }) { const [params, setParams] = useSearchParams(); const [query, setQuery] = useState(params.get("q") ?? ""); const [filters, setFilters] = useState<DocumentFilters>({ ...emptyFilters, product: params.get("product") ?? "", sampleManagerVersion: params.get("sampleManagerVersion") ?? "", solution: params.get("solution") ?? "", module: params.get("module") ?? "", documentType: params.get("documentType") ?? "", language: params.get("language") ?? "" }); const [includeCases, setIncludeCases] = useState(params.get("includeCases") === "true"); const [results, setResults] = useState<SearchResultRecord[]>([]); const [error, setError] = useState(""); const [copied, setCopied] = useState(""); const syncUrl = () => { const next = new URLSearchParams(params); query.trim() ? next.set("q", query.trim()) : next.delete("q"); includeCases && scope.projectId ? next.set("includeCases", "true") : next.delete("includeCases"); Object.entries(filters).forEach(([key, value]) => value ? next.set(key, value) : next.delete(key)); setParams(next, { replace: true }); }; const search = async () => { syncUrl(); setError(""); setResults([]); try { const product = record(await api.productDocumentSearch({ q: query, ...filters, ...buildKnowledgeScope(scope), limit: 50 })); let all = records(product.results); if (includeCases && scope.projectId && query.trim()) { const project = record(await api.memorySearch({ projectId: Number(scope.projectId), environment: scope.environment, q: query, sampleManagerVersion: filters.sampleManagerVersion || undefined, solution: filters.solution || undefined, module: filters.module || undefined, limit: 20 })); all = [...all, ...records(project.results).filter((result) => text(result.kind) !== "product_document")]; } setResults(all); } catch (err: unknown) { setError(err instanceof Error ? err.message : "Search failed"); } }; useEffect(() => { if (query.trim()) void search(); }, [scope.projectId, scope.environment]); const copyCitation = async (result: SearchResultRecord) => { const citation = `${text(result.title, "Product section")} · ${text(result.sectionPath ?? result.path, "section")} · v${text(result.sampleManagerVersion, "unknown")} · ${text(result.sourcePath ?? result.sourceLocator, "source unavailable")} · sha256:${text(result.sourceSha256, "unknown")}`; try { await navigator.clipboard.writeText(citation); setCopied(text(result.id)); window.setTimeout(() => setCopied(""), 1500); } catch { setError("Clipboard access is unavailable. Copy the citation text manually."); } }; return <div className="space-y-4"><FilterToolbar query={query} onQuery={setQuery} filters={filters} onFilter={(key, value) => setFilters((old) => ({ ...old, [key]: value }))} onApply={() => void search()} activeCount={Object.values(filters).filter(Boolean).length} onClear={() => setFilters(emptyFilters)}><label className="flex items-center gap-2 text-sm text-[var(--ui-muted)]"><input type="checkbox" checked={includeCases} onChange={(event) => setIncludeCases(event.target.checked)} disabled={!scope.projectId} /> Include project Cases</label></FilterToolbar>{error && <ErrorState message={error} />}{results.length === 0 && !error ? <EmptyState title={query ? "No matching product sections" : "Search product docs"} description={query ? "Try a broader query or clear a filter." : "Enter a query to search authoritative product documentation."} /> : <DataTable><thead><tr><th>Title</th><th>Type</th><th>Section</th><th>Source</th><th /></tr></thead><tbody>{results.map((result, index) => <tr key={`${text(result.id)}-${index}`}><td><Link to={withKnowledgeScope(text(result.kind) === "product_document" ? `/knowledge/product-docs?document=${encodeURIComponent(text(result.id))}` : `/knowledge/cases?document=${encodeURIComponent(text(result.id))}`, knowledgeItemScope(result, scope))} className="font-medium hover:text-[var(--ui-mint)]">{text(result.title)}</Link><p className="mt-1 max-w-[360px] truncate text-xs text-[var(--ui-muted)]">{text(result.summary ?? result.snippet ?? result.body, "")}</p></td><td><Badge tone={text(result.kind) === "product_document" ? "iris" : "sun"}>{text(result.kind) === "product_document" ? "Product" : "Project case"}</Badge></td><td>{text(result.sectionPath ?? result.path)}</td><td>{text(result.sourcePath ?? result.sourceLocator)}</td><td><button className="ui-button ui-button-ghost ui-button-sm" onClick={() => void copyCitation(result)}>{copied === text(result.id) ? <Check size={14} /> : <Copy size={14} />}{copied === text(result.id) ? "Copied" : "Copy citation"}</button></td></tr>)}</tbody></DataTable>}</div>; }

function ImportRunRecordDrawerFromUrl({ id, onClose }: { id: string; onClose: () => void }) { const [run, setRun] = useState<ImportRunRecord>(); const [error, setError] = useState(""); const load = () => api.productDocumentImportDetail(id).then((result) => setRun(record(result))).catch((err: unknown) => setError(err instanceof Error ? err.message : "Unable to load import details")); useEffect(() => { load(); }, [id]); if (error) return <Drawer title="Import run" onClose={onClose}><ErrorState message={error} onRetry={load} /></Drawer>; if (!run) return <Drawer title="Import run" onClose={onClose}><LoadingState label="Loading import details" /></Drawer>; return <ImportRunDrawer run={run} onClose={onClose} onRefresh={load} />; }
export default function KnowledgeProduct() {
  const location = useLocation();
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const { projectId: contextProjectId } = useProjectScope();
  const { user } = useAuth();
  const [importOpen, setImportOpen] = useState(false);
  const [indexError, setIndexError] = useState("");
  const [indexBusy, setIndexBusy] = useState(false);
  const path = location.pathname;
  const section = path.includes("/imports") ? "imports" : path.includes("/versions") ? "versions" : path.includes("/search") ? "search" : path.includes("/topics") ? "topics" : "docs";
  const scope = buildKnowledgeScope({ projectId: params.get("projectId") ?? (contextProjectId ? String(contextProjectId) : undefined), environment: params.get("environment") ?? undefined });
  const selectedDocument = params.get("document") ?? "";
  const selectedTopic = section === "topics" ? params.get("topic") ?? "" : "";
  const selectedRun = section === "imports" ? params.get("run") ?? "" : "";
  const selectedGroup = section === "versions" ? params.get("group") ?? "" : "";
  const closeParam = (key: string) => { const next = new URLSearchParams(params); next.delete(key); navigate(`${path}${next.toString() ? `?${next.toString()}` : ""}`); };
  const refreshIndex = async () => { setIndexBusy(true); setIndexError(""); try { await api.knowledgeOperationsRebuildIndex(undefined, `product-index-refresh:${Date.now()}`); } catch (err: unknown) { setIndexError(err instanceof Error ? err.message : "Index rebuild failed"); } finally { setIndexBusy(false); } };
  const title = section === "docs" ? "Product docs" : section === "imports" ? "Imports" : section === "topics" ? "Topics" : section === "versions" ? "Versions and diffs" : "Search";
  const description = section === "docs" ? "Versioned documentation. Import, compare and search." : section === "imports" ? "Import history, metadata inference and audit." : section === "topics" ? "Logical topics with shared immutable revisions and bindings." : section === "versions" ? "Compare structural changes between immutable document revisions." : "Find source-backed product sections and project case evidence.";
  return <div className="min-h-full p-4 sm:p-6 lg:p-8"><div className="mx-auto max-w-[1600px]"><PageHeader title={title} description={description} actions={section === "docs" && user?.isAdmin ? <><button className="ui-button ui-button-primary" onClick={() => setImportOpen(true)}><Import size={15} /> Import documents</button><button className="ui-button ui-button-ghost" disabled={indexBusy} onClick={() => void refreshIndex()}><RefreshCw size={15} className={indexBusy ? "animate-spin" : ""} /> Rebuild index</button></> : undefined} /><PageTabs active={section} scope={scope} />{indexError && <p className="ui-field-error my-4">{indexError}</p>}<div className="mt-6">{section === "docs" && <ProductList scope={scope} selectedId={selectedDocument} onSelect={(id, sourceScope) => navigate(withKnowledgeScope(`/knowledge/product-docs?document=${encodeURIComponent(id)}`, sourceScope))} onImport={user?.isAdmin ? () => setImportOpen(true) : undefined} />}{section === "imports" && user?.isAdmin && <ProductImportRuns onImport={() => setImportOpen(true)} onSelectRun={(id) => { const next = new URLSearchParams(params); next.set("run", id); navigate(`${path}?${next.toString()}`); }} />}{section === "topics" && <ProductTopics scope={scope} selectedId={selectedTopic} onSelect={(id) => { const next = new URLSearchParams(params); id ? next.set("topic", id) : next.delete("topic"); navigate(`${path}${next.toString() ? `?${next.toString()}` : ""}`); }} />}{section === "versions" && <ProductVersions scope={scope} groupId={selectedGroup} onSelect={(id) => { const next = new URLSearchParams(params); id ? next.set("group", id) : next.delete("group"); navigate(`${path}${next.toString() ? `?${next.toString()}` : ""}`); }} />}{section === "search" && <ProductSearch scope={scope} />}</div>{selectedDocument && section === "docs" && <ProductDetail id={selectedDocument} scope={scope} onClose={() => closeParam("document")} />}{selectedRun && section === "imports" && user?.isAdmin && <ImportRunRecordDrawerFromUrl id={selectedRun} onClose={() => closeParam("run")} />}{importOpen && user?.isAdmin && <ImportDialog scope={scope} onClose={() => setImportOpen(false)} onComplete={() => { setImportOpen(false); window.dispatchEvent(new Event("product-import-completed")); }} />}</div></div>;
}
